function validate([nums, limit]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value in nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 1000000000) return 'limit is an integer from 1 to 10^9.';
  return null;
}

