function lexicographicallySmallestArray(nums, limit) {
  const n = nums.length;
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums[a] - nums[b]);
  const result = new Array(n);
  let start = 0;
  while (start < n) {
    let end = start + 1;
    while (end < n && nums[order[end]] - nums[order[end - 1]] <= limit) {
      end++;
    }
    const positions = order.slice(start, end).sort((a, b) => a - b);
    for (let k = 0; k < positions.length; k++) {
      result[positions[k]] = nums[order[start + k]];
    }
    start = end;
  }
  return result;
}

