function lexicographicallySmallestArray(nums, limit) {
  const n = nums.length;
  const group = new Array(n).fill(-1);
  let groups = 0;
  for (let s = 0; s < n; s++) {
    if (group[s] !== -1) continue;
    group[s] = groups;
    const stack = [s];
    while (stack.length) {
      const u = stack.pop();
      for (let v = 0; v < n; v++) {
        if (group[v] === -1 && Math.abs(nums[u] - nums[v]) <= limit) {
          group[v] = groups;
          stack.push(v);
        }
      }
    }
    groups++;
  }
  const out = nums.slice();
  for (let g = 0; g < groups; g++) {
    const idx = [];
    for (let i = 0; i < n; i++) if (group[i] === g) idx.push(i);
    const vals = idx.map(i => nums[i]).sort((a, b) => a - b);
    idx.forEach((i, t) => { out[i] = vals[t]; });
  }
  return out;
}

