function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 8);
    const top = 1 + Math.floor(rand() * 20);
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    const limit = 1 + Math.floor(rand() * 5);
    return [nums, limit];
  }
  const n = 2000;
  const ranges = [1000000000, 100000, 5000];
  const range = ranges[Math.floor(rand() * ranges.length)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * range));
  const limit = Math.max(1, Math.floor((range / n) * (0.3 + rand() * 2)));
  return [nums, limit];
}
